export const FRAMES=Object.freeze(['narrow','balanced']);export const POSES=Object.freeze(['neutral','guard','punch','walk']);export const TORSO_LEG=Object.freeze(['torso_leaning','balanced','leg_leaning']);export const ARM_LENGTH=Object.freeze(['short','average','long']);export const INTERNAL_ARM=Object.freeze(['upper_arm_dominant','balanced','forearm_dominant']);export const CLAVICLE=Object.freeze(['compact','proportional','extended']);export const PELVIS=Object.freeze(['narrow','proportional','broad']);export const CLOTHING=Object.freeze(['fitted','outer']);
const FRAME=Object.freeze({narrow:{shoulder:22,torsoWidth:18},balanced:{shoulder:19,torsoWidth:24}});
const TORSO_LEG_GEOMETRY=Object.freeze({torso_leaning:{hipY:46},balanced:{hipY:44},leg_leaning:{hipY:42}});
const ARM_LENGTH_GEOMETRY=Object.freeze({short:12,average:15,long:18});
const INTERNAL_ARM_GEOMETRY=Object.freeze({upper_arm_dominant:.60,balanced:.50,forearm_dominant:.40});
const CLAVICLE_GEOMETRY=Object.freeze({compact:-2,proportional:0,extended:2});
const PELVIS_GEOMETRY=Object.freeze({narrow:2,proportional:0,broad:-2});
const ARM_POSE_GEOMETRY=Object.freeze({neutral:{y:43,extra:0},guard:{y:25,extra:1},punch:{y:28,extra:10},walk:{y:42,extra:0}});
const LEG_POSE_GEOMETRY=Object.freeze({neutral:[0,0],guard:[0,0],punch:[-1,1],walk:[-3,3]});
const BODY_TOP_Y=6, SHOULDER_Y=28, FOOT_Y=62;
export const ASSET_ACCOUNTING=Object.freeze({logicalPresentationRequirements:3888,naiveCartesianFullBodies:3888,uniqueRasterComponents:9,classificationCounts:Object.freeze({SHARED:4,METADATA_ONLY:4,STRUCTURE_SPECIFIC:2,PROPORTION_SPECIFIC:0,POSE_SPECIFIC:0,STRUCTURE_X_POSE:0,PROPORTION_X_POSE:0,CLOTHING_SPECIFIC:1,STRUCTURE_X_CLOTHING:2,PROPORTION_X_CLOTHING:0,CLOTHING_X_POSE:0,STRUCTURE_X_CLOTHING_X_POSE:0,PROPORTION_X_CLOTHING_X_POSE:0,COMPOSITE_EXCEPTION:0}),worstBoundary:'Structural Frame × fitted torso garment',avoidedVariants:3879});
function known(v,c,n){if(!c.includes(v))throw new Error(`unknown ${n}: ${v}`)}function p(x,y){return Object.freeze({x,y})}
export function resolveMorphology(options={}){const s={frame:'balanced',torsoLeg:'balanced',armLength:'average',internalArm:'balanced',clavicle:'proportional',pelvic:'proportional',pose:'neutral',clothing:'fitted',...options};known(s.frame,FRAMES,'frame');known(s.pose,POSES,'pose');known(s.torsoLeg,TORSO_LEG,'torsoLeg');known(s.armLength,ARM_LENGTH,'armLength');known(s.internalArm,INTERNAL_ARM,'internalArm');known(s.clavicle,CLAVICLE,'clavicle');known(s.pelvic,PELVIS,'pelvic');known(s.clothing,CLOTHING,'clothing');const f=FRAME[s.frame],hipY=TORSO_LEG_GEOMETRY[s.torsoLeg].hipY,span=f.shoulder-CLAVICLE_GEOMETRY[s.clavicle],reach=ARM_LENGTH_GEOMETRY[s.armLength]+ARM_POSE_GEOMETRY[s.pose].extra,arm=ARM_POSE_GEOMETRY[s.pose],shoulders={left:p(span,SHOULDER_Y),right:p(64-span,SHOULDER_Y)},pelvis=PELVIS_GEOMETRY[s.pelvic],hips={left:p(27+pelvis,hipY),right:p(37-pelvis,hipY)},hr=p(shoulders.right.x+reach,arm.y),hl=p(shoulders.left.x-(s.pose==='guard'?7:ARM_LENGTH_GEOMETRY[s.armLength]),s.pose==='guard'?25:43),frac=INTERNAL_ARM_GEOMETRY[s.internalArm],elbows={left:p(Math.round(shoulders.left.x+(hl.x-shoulders.left.x)*frac),Math.round(shoulders.left.y+(hl.y-shoulders.left.y)*frac)),right:p(Math.round(shoulders.right.x+(hr.x-shoulders.right.x)*frac),Math.round(shoulders.right.y+(hr.y-shoulders.right.y)*frac))},ld=LEG_POSE_GEOMETRY[s.pose],a=Object.freeze({head:p(32,14),eye_left:p(29,13),eye_right:p(35,13),nose:p(32,16),mouth:p(32,19),shoulder_left:shoulders.left,shoulder_right:shoulders.right,hip_left:hips.left,hip_right:hips.right,knee_left:p(hips.left.x+ld[0],53),knee_right:p(hips.right.x+ld[1],53),foot_left:p(hips.left.x+ld[0],FOOT_Y),foot_right:p(hips.right.x+ld[1],FOOT_Y),elbow_left:elbows.left,elbow_right:elbows.right,hand_left:hl,hand_right:hr}),garment=s.clothing==='fitted'?`fitted.${s.frame}`:'outer.shared',totalLegLength=a.foot_left.y-a.hip_left.y,torsoLength=a.hip_left.y-SHOULDER_Y;return Object.freeze({...s,rig:'humanoid_morphology_pixel_v1',anchors:a,measurements:Object.freeze({totalHeight:FOOT_Y-BODY_TOP_Y,torsoLength,totalLegLength,shoulderToWrist:reach,torsoWidth:f.torsoWidth}),semantic:Object.freeze({leftArm:s.pose==='guard'?'guard':'neutral',rightArm:s.pose==='punch'?'punch_extended':s.pose==='guard'?'guard':'neutral',leftLeg:s.pose==='walk'?'forward':'neutral',rightLeg:s.pose==='walk'?'back':'neutral'}),components:Object.freeze(['head.shared',`torso.${s.frame}`,'arm.shared','leg.shared',garment,'weapon.shared.blade']),attachment:Object.freeze({id:'blade',anchor:'hand_right',point:hr})})}
const files=Object.freeze({head:'components/shared/head.png',torso:{narrow:'components/narrow/torso.png',balanced:'components/balanced/torso.png'},arm:'components/shared/arm.png',leg:'components/shared/leg.png',fitted:{narrow:'components/clothing/fitted-narrow.png',balanced:'components/clothing/fitted-balanced.png'},outer:'components/clothing/outer.png',blade:'components/shared/blade.png'}),cache=new Map();function load(path){if(!cache.has(path)){const i=new Image();i.src=path;cache.set(path,i)}return cache.get(path)}function img(ctx,path,x,y){const i=load(path);if(i.complete)ctx.drawImage(i,Math.round(x),Math.round(y))}
export function drawMorphology(ctx,m,debug=false){ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,64,64);ctx.fillStyle='#17202a';ctx.fillRect(0,0,64,64);const a=m.anchors,garmentX=a.shoulder_left.x-2,garmentY=27+Math.round((a.hip_left.y-44)/2);img(ctx,files.leg,a.hip_left.x-4,a.hip_left.y);img(ctx,files.leg,a.hip_right.x-4,a.hip_right.y);img(ctx,files.torso[m.frame],32-m.measurements.torsoWidth/2-2,27);img(ctx,files.head,24,6);img(ctx,files.arm,a.shoulder_left.x-4,27);img(ctx,files.arm,a.shoulder_right.x-4,27);img(ctx,m.clothing==='fitted'?files.fitted[m.frame]:files.outer,garmentX,garmentY);img(ctx,files.blade,a.hand_right.x+1,a.hand_right.y-14);if(debug){ctx.fillStyle='#ffdf69';Object.entries(a).forEach(([id,q])=>{ctx.fillRect(q.x-1,q.y-1,3,3);ctx.fillStyle='#fff';ctx.font='3px monospace';ctx.fillText(id,q.x+2,q.y);ctx.fillStyle='#ffdf69'})}}
function init(){const canvas=document.querySelector('#preview');if(!canvas)return;const form=document.querySelector('#controls'),details=document.querySelector('#details'),debug=document.querySelector('#debug'),render=()=>{const state=Object.fromEntries(new FormData(form)),m=resolveMorphology(state);drawMorphology(canvas.getContext('2d'),m,debug.checked);details.textContent=JSON.stringify({state,measurements:m.measurements,anchors:m.anchors,components:m.components,accounting:ASSET_ACCOUNTING},null,2)};form.addEventListener('change',render);debug.addEventListener('change',render);render()}if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',init);
